-- An assessment definition identifier such as "1" or "2026.1": short, no spaces.
ALTER TABLE "financial_literacy_profiles"
    ADD CONSTRAINT "financial_literacy_profiles_assessment_version_format_check" CHECK ("assessment_version" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,19}$');

-- Topic lifecycle: NOT_STARTED has no timestamps, IN_PROGRESS has started_at only, COMPLETED has
-- both. The allowed transitions (never back from COMPLETED) are enforced by the service.
-- "assessed_at is not in the future" is also checked by the service: a CHECK constraint cannot
-- use now().
ALTER TABLE "financial_literacy_topic_progress"
    ADD CONSTRAINT "financial_literacy_topic_progress_status_timestamps_check" CHECK (
        ("status" = 'NOT_STARTED' AND "started_at" IS NULL AND "completed_at" IS NULL)
        OR ("status" = 'IN_PROGRESS' AND "started_at" IS NOT NULL AND "completed_at" IS NULL)
        OR ("status" = 'COMPLETED' AND "started_at" IS NOT NULL AND "completed_at" IS NOT NULL)
    ),
    ADD CONSTRAINT "financial_literacy_topic_progress_completed_after_started_check" CHECK ("completed_at" IS NULL OR "completed_at" >= "started_at");
